const root=new THREE.Group();scene.add(root);
function blob(parent,color,pos,scale,material){const m=new THREE.Mesh(new THREE.SphereGeometry(1,32,24),material||mat(color));m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function tube(parent,pts,radius,color){const curve=new THREE.CatmullRomCurve3(pts.map(p=>new THREE.Vector3(...p)));const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,48,radius,8,false),mat(color,.48));mesh.castShadow=true;parent.add(mesh);return mesh}
// Legs and trainers
