document.getElementById('hit').addEventListener('click',danceHit);window.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat){e.preventDefault();danceHit()}});
document.getElementById('tempo').onclick=()=>{bpm=bpm>=148?88:bpm+10;document.getElementById('bpm').textContent=bpm};document.getElementById('sound').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫ SOM: ON':'♪ SOM: OFF';ping(660)};
renderer.domElement.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(drag){targetRot+=(e.clientX-lastX)*.006;lastX=e.clientX}});renderer.domElement.addEventListener('pointerup',()=>drag=false);renderer.domElement.addEventListener('wheel',e=>{zoom=THREE.MathUtils.clamp(zoom+e.deltaY*.008,6,11)});
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;const beatLen=60/bpm,phase=(elapsed%beatLen)/beatLen;bar.style.transform=`translateX(${phase*330-100}%)`;
 const wave=Math.sin(elapsed*Math.PI*2*(bpm/60));const quick=Math.sin(elapsed*Math.PI*4*(bpm/60));const kick=Math.max(0,1-phase*4);
 waist.position.y=1.27+.045*Math.abs(wave)+hitPulse*.08;waist.rotation.y=Math.sin(elapsed*3.3)*.10+quick*.035;waist.rotation.z=Math.sin(elapsed*2.7)*.055;waist.scale.z=1+Math.abs(wave)*.035+hitPulse*.06;
 torso.rotation.z=Math.sin(elapsed*2.7+.5)*.045;torso.rotation.y=-waist.rotation.y*.55;root.position.y=.035*Math.sin(elapsed*Math.PI*2*(bpm/60))+.035+hitPulse*.07;
 legs[0].rotation.z=.055*Math.sin(elapsed*2.7);legs[1].rotation.z=-.055*Math.sin(elapsed*2.7);legs[0].rotation.x=.045*Math.sin(elapsed*4);legs[1].rotation.x=-.045*Math.sin(elapsed*4);
 hitPulse=Math.max(0,hitPulse-dt*2.8);rot+=(targetRot-rot)*.08;camera.position.x=Math.sin(rot)*zoom*.10;camera.position.z=zoom;camera.lookAt(0,1.15,0);camera.position.z=zoom;renderer.render(scene,camera)}animate();
